//! Compatibility evidence captured before extraction from Heron.
//!
//! The immutable fixture was generated by the original `heron-sine` at Heron
//! commit 3bb8209aaaccce6fb5ab1e27e725c58a8cc0e5e6 (suite 0.6.4, Truce 6.3.0),
//! using `Params::set_plain` followed by `truce::core::state::snapshot_plugin`.
//! Its nondefault values below must survive repository and release changes.

use std::time::Duration;

use heron_sine::{Plugin, SineParamsParamId as P};
use truce::core::PluginRuntime;
use truce::prelude::*;
use truce_test::driver;

const LEGACY_STATE: &[u8] = include_bytes!("fixtures/heron-0.6.4-nondefault.pluginstate");

#[test]
fn released_identity_and_editor_composition_are_preserved() {
    let info = Plugin::info();
    assert_eq!(info.clap_id, "live.minori.heron.sine");
    assert_eq!(
        truce::core::state::vst3_cid(info.vst3_id),
        [
            0xfa, 0x1d, 0x35, 0xc1, 0xdd, 0x4d, 0x4a, 0x4b, 0xc1, 0xf3, 0x08, 0x96, 0xf6, 0xd9,
            0xdf, 0x76
        ],
    );
    assert_eq!(info.au_manufacturer, *b"HRON");
    assert_eq!(info.fourcc, *b"HRSN");
    assert_eq!(info.au_type, *b"aumu");
    let plugin = Plugin::create();
    let editor = plugin.editor_builder()(plugin.params_arc()).expect("Heron sine ships an editor");
    assert_eq!(editor.size(), heron_plugin_ui::SINE_EDITOR_SIZE);
}

#[test]
fn restores_heron_0_6_4_nondefault_state_and_sound() {
    let restored = driver!(Plugin)
        .duration(Duration::from_millis(400))
        .state_blob(LEGACY_STATE.to_vec())
        .script(|script| {
            script.note_on(69, 0.8);
            script.wait_ms(30);
            script.note_off(69);
        })
        .run();
    for (id, expected) in [(P::Output, -9.0), (P::Attack, 17.0), (P::Release, 250.0)] {
        let actual = restored.plugin.params().get_plain(id.into()).unwrap();
        assert!(
            (actual - expected).abs() < 0.0001,
            "historical parameter {id:?} restored as {actual}, expected {expected}",
        );
    }
    let configured = driver!(Plugin)
        .duration(Duration::from_millis(400))
        .setup(|plugin, _| {
            plugin.params().set_plain(P::Output.into(), -9.0);
            plugin.params().set_plain(P::Attack.into(), 17.0);
            plugin.params().set_plain(P::Release.into(), 250.0);
            plugin.params().snap_smoothers();
        })
        .script(|script| {
            script.note_on(69, 0.8);
            script.wait_ms(30);
            script.note_off(69);
        })
        .run();
    assert_eq!(restored.output, configured.output);
}
